"use strict";(self.webpackChunkdlabs_mobile_apps_github_io=self.webpackChunkdlabs_mobile_apps_github_io||[]).push([[2439],{7408:a=>{a.exports=JSON.parse('{"label":"tools","permalink":"/docs/tags/tools","allTagsPath":"/docs/tags","count":3,"items":[{"id":"tools/app-link","title":"App Link","description":"App/Universal link (universal link for ios, app link for android) is technique that mobile platforms android and ios use to open the application via a link.","permalink":"/docs/tools/app-link"},{"id":"tools/crashlytics","title":"Crashlytics","description":"Crashlytics helps you to collect analytics and details about crashes and errors that occur in your app. It does this through three aspects there are [Logs]  Log events in your app to be sent with the crash report for context if your app crashes, [Crash] reports Every crash is automatically turned into a crash report and sent when the application next opens and [Stack traces]  Even when an error is caught and your app recovers, the Dart stack trace can still be sent.","permalink":"/docs/tools/crashlytics"},{"id":"tools/flavors/flavors","title":"Flavors","description":"Flavors (known as build configurations in iOS and macOS), allow you (the developer) to create separate environments for your app using the same code base. For example, you might have one flavor for your full-fledged production app, another as a limited \\"free\\" app, another for testing experimental features, and so on.","permalink":"/docs/tools/flavors/"}]}')}}]);